    """
    Fused kernel: copy A->LU, LU decomposition with partial pivoting,
    forward substitution, backward substitution.

    Each program handles one batch element.
    A columns vectorized via BLOCK_N, RHS columns vectorized via BLOCK_K.
    LU workspace is separate from A so autotune re-runs start from fresh A.
    """
    batch_idx = tl.program_id(0)

    # Vector indices
    a_cols = tl.arange(0, BLOCK_N)
    b_cols = tl.arange(0, BLOCK_K)
    a_col_mask = a_cols < n
    b_col_mask = b_cols < nrhs

    a_base = A + batch_idx * a_batch_stride
    lu_base = LU + batch_idx * lu_batch_stride
    b_base = B + batch_idx * b_batch_stride
    x_base = X + batch_idx * x_batch_stride

    # Copy A to LU workspace (vectorized over columns)
    i = 0
    while i < n:
        row = tl.load(a_base + i * a_row_stride + a_cols, mask=a_col_mask, other=0.0)
        tl.store(lu_base + i * lu_row_stride + a_cols, row, mask=a_col_mask)
        i += 1

    # Copy B to X (vectorized over RHS columns)
    i = 0
    while i < n:
        bi = tl.load(b_base + i * b_row_stride + b_cols, mask=b_col_mask, other=0.0)
        tl.store(x_base + i * x_row_stride + b_cols, bi, mask=b_col_mask)
        i += 1

    # Step 1: LU decomposition with partial pivoting on LU workspace
    k = 0
