        pivot_row = k
        i = k + 1
        while i < n:
            val = tl.abs(tl.load(lu_base + i * lu_row_stride + k))
            if val > max_val:
                max_val = val
                pivot_row = i
            i += 1

        # Swap rows k and pivot_row - vectorized
