            tl.store(lu_base + k * lu_row_stride + a_cols, lup_row, mask=a_col_mask)
            tl.store(
                lu_base + pivot_row * lu_row_stride + a_cols,
                luk_row,
                mask=a_col_mask,
            )
            # Swap X rows
            xk = tl.load(x_base + k * x_row_stride + b_cols, mask=b_col_mask, other=0.0)
            xp = tl.load(
                x_base + pivot_row * x_row_stride + b_cols,
                mask=b_col_mask,
                other=0.0,
            )
            tl.store(x_base + k * x_row_stride + b_cols, xp, mask=b_col_mask)
            tl.store(x_base + pivot_row * x_row_stride + b_cols, xk, mask=b_col_mask)

